8: interface AccountSelectorProps {
9:   accounts: Account[];
10:   selectedAccountId: string | null;
11:   onAccountChange: (accountId: string) => void;
12: }
13: 
14: function getAccountLabel(account: Account): string {
15:   return formatAccountLabel(account.type, account.id);
16: }
17: 
18: function getSelectedAccountLabel(
19:   selectedAccountId: string | null,
20:   accounts: Account[]
21: ): string {
22:   if (!selectedAccountId || accounts.length === 0) {
23:     return MESSAGES.SELECT_ACCOUNT;
24:   }
25:   const account =
26:     accounts.find((acc) => acc.id === selectedAccountId) || accounts[0];
27:   return getAccountLabel(account);
28: }
29: 
30: export function AccountSelector({
31:   accounts,
32:   selectedAccountId,
33:   onAccountChange,
34: }: AccountSelectorProps) {
35:   if (accounts.length === 0) {
36:     return null;
37:   }
38: 
39:   return (
40:     <div className={styles.accountSelectWrapper}>
41:       <Dropdown
42:         items={accounts.map((account) => ({
43:           label: getAccountLabel(account),
44:           value: account.id,
45:           onClick: () => {},
46:         }))}
47:         placeholder={getSelectedAccountLabel(selectedAccountId, accounts)}
48:         onValueChange={() => {}}
49:         width="100%"
50:       />
51:     </div>
52:   );
53: }

