1: import { getApiBaseUrl } from "@/config/api.config";
2: import {
3:   getLocalStorageItem,
4:   removeLocalStorageItem,
5:   isWindowAvailable,
6: } from "./windowUtils";
7: import { STORAGE_KEYS, ROUTES } from "@/constants";
8: 
9: function getAuthToken(): string | null {
10:   return getLocalStorageItem(STORAGE_KEYS.TOKEN);
11: }
12: 
13: export async function fetchApi(
14:   url: string,
15:   options: RequestInit = {}
16: ): Promise<Response> {
17:   const token = getAuthToken();
18:   const headers: HeadersInit = {
19:     "Content-Type": "application/json",
20:     ...options.headers,
21:   };
22: 
23:   if (token) {
24:     headers["Authorization"] = `Bearer ${token}`;
25:   }
26: 
27:   const API_BASE_URL = getApiBaseUrl();
28: 
29:   try {
30:     const response = await fetch(`${API_BASE_URL}${url}`, {
31:       ...options,
32:       headers,
33:     });
34: 
35:     if (!response.ok) {
36:       if (response.status === 401) {
37:         removeLocalStorageItem(STORAGE_KEYS.TOKEN);
38:         if (isWindowAvailable()) {
39:           window.location.href = ROUTES.AUTH;
40:         }
41:         const errorText = await response
42:           .text()
43:           .catch(() => response.statusText);
44:         throw new Error(`Erro na requisição: ${response.status} ${errorText}`);
45:       }
46:       const errorText = await response.text().catch(() => response.statusText);
47:       throw new Error(`Erro na requisição: ${response.status} ${errorText}`);
48:     }
49: 
50:     return response;
51:   } catch (error) {
52:     if (error instanceof TypeError && error.message.includes("fetch")) {
53:       throw new Error(
54:         "Erro de conexão: Não foi possível conectar ao servidor. Verifique se o backend está rodando."
55:       );
56:     }
57:     if (error instanceof Error && error.message.includes("CORS")) {
58:       throw new Error(
59:         "Erro de CORS: O servidor não permite requisições desta origem."
60:       );
61:     }
62:     throw error;
63:   }
64: }

1: import { useState, useEffect, useCallback } from "react";
2: import { fetchAccounts, Account } from "@/api/account.api";
3: import { getAccountId, setAccountId } from "@/utils/accountStorage";
4: import { MESSAGES } from "@/constants";
5: 
6: interface UseAccountsReturn {
7:   accounts: Account[];
8:   selectedAccountId: string | null;
9:   loading: boolean;
10:   error: string | null;
11:   handleAccountChange: (accountId: string) => void;
12:   retryLoadAccounts: () => void;
13: }
14: 
15: export function useAccounts(): UseAccountsReturn {
16:   const [accounts, setAccounts] = useState<Account[]>([]);
17:   const [selectedAccountId, setSelectedAccountId] = useState<string | null>(
18:     null
19:   );
20:   const [loading, setLoading] = useState<boolean>(true);
21:   const [error, setError] = useState<string | null>(null);
22: 
23:   const loadAccounts = useCallback(async () => {
24:     try {
25:       setLoading(true);
26:       setError(null);
27:       const accountsData = await fetchAccounts();
28:       setAccounts(accountsData);
29: 
30:       if (accountsData.length > 0) {
31:         // Sempre seta o primeiro item do array no localStorage
32:         const firstAccountId = accountsData[0].id;
33:         setSelectedAccountId(firstAccountId);
34:         setAccountId(firstAccountId);
35:       }
36:     } catch (err) {
37:       const errorMessage =
38:         err instanceof Error ? err.message : MESSAGES.ERROR_LOADING_ACCOUNTS;
39:       setError(errorMessage);
40:       console.error("Erro ao carregar contas:", err);
41: 
42:       const storedAccountId = getAccountId();
43:       if (storedAccountId) {
44:         setSelectedAccountId(storedAccountId);
45:       }
46:     } finally {
47:       setLoading(false);
48:     }
49:   }, []);
50: 
51:   useEffect(() => {
52:     loadAccounts();
53:   }, [loadAccounts]);
54: 
55:   const handleAccountChange = useCallback((accountId: string) => {
56:     setSelectedAccountId(accountId);
57:     setAccountId(accountId);
58:   }, []);
59: 
60:   return {
61:     accounts,
62:     selectedAccountId,
63:     loading,
64:     error,
65:     handleAccountChange,
66:     retryLoadAccounts: loadAccounts,
67:   };
68: }

